const DATE_FORMATS = {
  time: { hour: "numeric", minute: "2-digit", hour12: true },
  date: { month: "short", day: "numeric", year: "numeric" },
  datetime: { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit", hour12: true },
  "long-date": { weekday: "long", month: "long", day: "numeric" },
  full: { dateStyle: "full", timeStyle: "full" },
  "full-date": { dateStyle: "full" }
}
const RELATIVE_DAYS = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })

export function signedDifferenceInDays(fromDate, toDate) {
  // Rounding accounts for local days that are 23 or 25 hours long during DST.
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const result = new Date(date)
  result.setHours(0, 0, 0, 0)
  return result
}

export function parseLocalTime(timestamp) {
  // A timeline heading is a calendar date, not a midnight UTC timestamp.
  return new Date(/^\d{4}-\d{2}-\d{2}$/.test(timestamp) ? `${timestamp}T00:00:00` : timestamp || NaN)
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (format === "relative") {
    return formatRelativeTime(date, now)
  } else if (format === "days") {
    return RELATIVE_DAYS.format(signedDifferenceInDays(now, date), "day")
  } else {
    return new Intl.DateTimeFormat("en-US", DATE_FORMATS[format] || DATE_FORMATS.datetime).format(date)
  }
}

function formatRelativeTime(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time")
  } else if (days > -7) {
    return RELATIVE_DAYS.format(days, "day")
  } else {
    const year = date.getFullYear() === now.getFullYear() ? undefined : "numeric"
    return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year }).format(date)
  }
}
